$groupNames = @{ PUB='01-PUBLIC'; AUTH='02-AUTH'; PER='03-PERSONAL'; ORG='04-ORGANIZATIONS'; BUS='05-BUSINESS'; PRG='06-PROGRAMS'; ADM='07-ADMIN'; SUP='10-SUPPORTING' }
$groupContent = @{}
$index = @('# سجل الصفحات والإجراءات', '', 'يُقرأ مع [عقد الواجهة](../20-UI-CONTRACT.md) و[الصلاحيات](../02-IDENTITY-ROLES-PERMISSIONS.md). جميع الأفعال ترث حالات الخطأ والتأكيد وidempotency حيث تنطبق. الجداول أدناه مواصفات مخططة لا إثبات تنفيذ.', '', '| الصفحة | المسار | الملف |', '|---|---|---|')
$permissionRows = @()
$pageCount = 0
$actionCount = 0
foreach ($line in ($catalog -split "`r?`n")) {
    if ([string]::IsNullOrWhiteSpace($line)) { continue }
    $fields = $line.Split('|')
    if ($fields.Count -ne 6) { throw "Invalid page row: $line" }
    $pageId, $title, $route, $owner, $data, $actionList = $fields
    $group = $pageId.Split('-')[0]
    $fileName = $groupNames[$group] + '.md'
    if (-not $groupContent.ContainsKey($group)) { $groupContent[$group] = @("# $($groupNames[$group]) — مواصفات الصفحات", '', 'كل إجراء أدناه يرث قواعد 20-UI-CONTRACT. حقول النماذج من 21-FORMS-VALIDATION؛ الصلاحيات الجديدة من 08-PERMISSION-EXTENSIONS في هذا المجلد.', '') }
    $groupContent[$group] += @("## $pageId — $title", '', "- **مسار الويب:** ``$route``", "- **السياق والمالك:** $owner", "- **البيانات والمحتوى:** $data", '- **القراءة:** GET للمورد المناظر من 11-API-CONTRACTS؛ scope على الخادم؛ DTO عامة/خاصة حسب السياق. أي عقد قراءة إضافي يثبت في OpenAPI قبل ربط الصفحة.', '- **الحالات المطلوبة:** تحميل، فارغ، فشل قراءة مع إعادة محاولة، ممنوع، غير موجود؛ وفي النماذج حفظ/تحقق/تعارض؛ وفي المال انتظار تأكيد خارجي.', '', '| Action ID | الزر/الإجراء | الصلاحية | العقد | شرط خاص ← النتيجة |', '|---|---|---|---|---|')
    $i = 0
    foreach ($action in $actionList.Split(';')) {
        $af = $action.Split('~')
        if ($af.Count -ne 4) { throw "Invalid action: $action" }
        $i++
        $actionId = '{0}.A{1:00}' -f $pageId, $i
        $groupContent[$group] += "| $actionId | $($af[0]) | $($af[1]) | ``$($af[2])`` | $($af[3]) |"
        $permissionRows += [pscustomobject]@{ Permission=$af[1]; Action=$actionId }
        $actionCount++
    }
    $groupContent[$group] += @('', "**قبول ${pageId}:** تنفيذ الأفعال المعلنة دون زر صامت؛ رفض actor غير مخول ومعرف مورد من جهة أخرى؛ اختبار حالة المورد غير المناسبة لكل mutation؛ تحقق عرض RTL وهاتف. الوصول إلى تبويبات/ملفات داخل الصفحة يعيد فحص الإذن ولا يكتفي بإذن الصفحة الأم.", '')
    $index += "| $pageId — $title | ``$route`` | [$fileName]($fileName) |"
    $pageCount++
}
foreach ($group in $groupNames.Keys) {
    Set-Content -LiteralPath (Join-Path $screenPath ($groupNames[$group] + '.md')) -Value ($groupContent[$group] -join "`n") -Encoding utf8
}
$index += @('', "عدد مواصفات الصفحات/مجموعات المسارات: **$pageCount**. عدد الأفعال الخاصة: **$actionCount**، إضافة إلى 19 إجراء عامًا موروثًا. بعض مجموعات الصفحة تجمع القائمة والتفاصيل أو المسودة والتحرير تحت عقد واحد، ويجب اختبار كل route variant.", '', 'تفاصيل الصلاحيات الموسعة: [08-PERMISSION-EXTENSIONS](08-PERMISSION-EXTENSIONS.md). لا يعني وجود endpoint في هذا السجل أنه منفذ بعد؛ يضاف إلى OpenAPI وخدمة المجال والاختبارات في مرحلته.')
Set-Content -LiteralPath (Join-Path $screenPath 'README.md') -Value ($index -join "`n") -Encoding utf8

