$roadmap = @('# 19 — خطة التنفيذ على أجزاء', '', 'الترتيب ملزم ما لم يوثق ADR سبب تغيير الاعتماديات. كل جزء جلسة أو عدة جلسات حسب حجم التنفيذ، وليس وعدًا بإنهاء هذا النظام في 14 جلسة قصيرة. لا تتجاوز اختبارات المال والعزل بحجة الانتقال للمرحلة التالية.', '', '| الجزء | الناتج | يعتمد على | برومبت التنفيذ |', '|---|---|---|---|')
foreach ($line in ($parts -split "`r?`n")) {
    if ([string]::IsNullOrWhiteSpace($line)) { continue }
    $f = $line.Split('|')
    if ($f.Count -ne 7) { throw "Invalid part row: $line" }
    $number, $title, $deps, $reads, $scope, $tests, $limits = $f
    $partName = "PART-$number"
    $body = @("# $partName — $title", '', '## البرومبت الجاهز لـCodex', '', "نفّذ هذه المرحلة محليًا داخل مستودع تمكين. اقرأ أولًا ../00-MASTER-PROMPT.md و../PROGRESS.md و../TRACEABILITY.md، ثم المراجع التالية من tamkeen-blueprint: **$reads**. الأرقام تشير إلى أسماء الملفات المرقمة في README. اقرأ كذلك سجلات screens المتعلقة بكل معرف صفحة أدناه.", '', "**الاعتماديات:** $deps. تحقق من الأدلة الفعلية، ولا تفترض أن مرحلة سابقة نفذت لمجرد وجود ملفها.", '', '## النطاق المطلوب', '', $scope, '', '## خطة عمل داخل الجزء', '', '1. افحص الوضع الحالي وحدد فرق المواصفة عن التنفيذ.', '2. ثبّت/حدّث schema وDTO وpermission policy وstate transitions المرتبطة بالنطاق.', '3. نفذ migration وخدمات المعاملات والـAPI قبل ربط واجهات الكتابة.', '4. نفذ الشاشات وأفعالها المسجلة؛ أضف IDs للأفعال اللازمة الجديدة.', '5. اربط البيانات من الخادم، وطبق loading/empty/error/conflict/forbidden والانتظار الخارجي.', '6. اختبر المسار السعيد والفشل والتزامن وعزل الجهات بما يناسب التغيير.', '7. راجع الواجهة بالعربية RTL على الهاتف وسطح المكتب، وعدل المشاكل قبل إغلاق الجزء.', '', '## قبول إلزامي', '', $tests, '', 'أضف typecheck/lint/build المناسبة للملفات المعدلة. الاختبار غير المشغل يسجل غير مشغل مع السبب، ولا يوصف بالناجح. استخدم PostgreSQL حقيقية لاختبار معاملات المال والسعة والعزل.', '', '## حدود المرحلة', '', $limits, '', '## تسليم ونقطة استئناف', '', 'حدّث PROGRESS.md وTRACEABILITY.md بأسماء ملفات الكود وأوامر الاختبار ونتائجها ومعرفات الأفعال المغطاة. اكتب في docs/qa/part-XX ملخص أدلة التشغيل والفشل المتوقع والـscreenshots عند وجود واجهة. إذا احتاج الجزء عدة جلسات، سجل آخر شريحة مكتملة وما بقي دون نقل حالة الجزء إلى مكتمل.', '', '### رسالة بدء قابلة للنسخ', '', "> اقرأ tamkeen-blueprint/parts/$partName.md ونفذه ضمن حدود 00-MASTER-PROMPT. استكمل الموجود، اربط الواجهة بالخادم والسياسات، نفذ معايير القبول، وحدث سجلي التقدم والتتبع. لا تبدأ الجزء التالي قبل تقرير نتيجة هذا الجزء.")
    Set-Content -LiteralPath (Join-Path $partPath "$partName.md") -Value ($body -join "`n") -Encoding utf8
    $roadmap += "| $partName | $title | $deps | [$partName](parts/$partName.md) |"
}
$roadmap += @('', '## ترتيب مراجعات المنتج', '', '- بعد PART-03: مراجعة اللغة البصرية عبر الشاشات الست، ثم إصلاح النظام قبل تكرار واجهاته.', '- بعد PART-07: تجربة متبرع وجمعية ومراجع مالي كاملة من إنشاء مشروع إلى تقرير إغلاق.', '- بعد PART-09: تجربة شركة ومستثمر وتخصيص مثبت محليًا.', '- بعد PART-12: تجربة شاب وراعٍ ومشغل ومدرب وصاحب عمل، بما فيها الانسحاب وعدم التوظيف.', '- بعد PART-14: عرض محلي كامل مع قائمة فجوات الإطلاق الحقيقي، دون ادعاء اعتماد مال أو ملكية من مجرد demo.', '', '## التقدم الآمن', '', 'إذا احتاج تكامل خارجي معلومة غير متاحة، سجل EXTERNAL_BLOCKED لهذا التكامل فقط واستمر باستخدام port محاكى واضح في العمل المستقل. تغيير architecture أو semantics الأموال يحتاج تحديث ADR والمواصفات والاختبارات المرتبطة قبل البناء عليه.')
Set-Content -LiteralPath (Join-Path $basePath '19-IMPLEMENTATION-ROADMAP.md') -Value ($roadmap -join "`n") -Encoding utf8
Write-Output "Generated $pageCount page specifications and $actionCount specific actions, plus 14 implementation parts."
